/* --- Bottom HUD: status icon rows + the 9-slot hotbar --- */

.hud-bottom {
  position: absolute;
  left: 50%;
  bottom: 6px;
  transform: translateX(-50%);
  z-index: 4;
  display: grid;
  justify-items: center;
  gap: 3px;
  pointer-events: auto;
  user-select: none;
}

.status-bars {
  display: flex;
  justify-content: space-between;
  width: 100%;
  gap: 12px;
}

.status-bars-left,
.status-bars-right {
  display: grid;
  gap: 2px;
}

.status-icon-row {
  display: flex;
  gap: 1px;
}

.status-icon-row.reversed {
  flex-direction: row-reverse;
}

.status-icon-row img {
  image-rendering: pixelated;
  filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.45));
}

.hotbar-area {
  position: relative;
  display: grid;
  justify-items: center;
}

.hotbar-item-name {
  position: absolute;
  top: -34px;
  color: var(--mc-text-light);
  font-size: 15px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
  opacity: 0;
  animation: hotbar-name-fade 2.2s ease-out forwards;
  pointer-events: none;
  white-space: nowrap;
}

@keyframes hotbar-name-fade {
  0% {
    opacity: 0;
  }
  8% {
    opacity: 1;
  }
  70% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

.hotbar {
  display: flex;
  padding: 3px;
  background: rgba(12, 12, 12, 0.5);
  border: 2px solid rgba(0, 0, 0, 0.62);
  outline: 1px solid rgba(255, 255, 255, 0.28);
}

.hotbar-slot {
  position: relative;
  width: 46px;
  height: 46px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  background: rgba(34, 34, 34, 0.42);
  border-style: solid;
  border-width: 2px;
  border-color: rgba(20, 20, 20, 0.85) rgba(125, 125, 125, 0.6) rgba(125, 125, 125, 0.6) rgba(20, 20, 20, 0.85);
}

.hotbar-slot.active::after {
  content: "";
  position: absolute;
  inset: -5px;
  border: 3px solid #fefefe;
  outline: 1px solid rgba(0, 0, 0, 0.55);
  pointer-events: none;
}

.hotbar-slot:hover {
  background: rgba(80, 80, 80, 0.45);
}

/* --- Item icons (shared by hotbar and inventory slots) --- */

.item-icon {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.item-icon img {
  image-rendering: pixelated;
}

.item-icon-count {
  position: absolute;
  right: -4px;
  bottom: -6px;
  font-size: 14px;
  font-weight: 700;
  color: var(--mc-text-light);
  text-shadow: var(--mc-text-shadow);
  pointer-events: none;
}

.item-icon-durability {
  position: absolute;
  left: 1px;
  right: 1px;
  bottom: -2px;
  height: 3px;
  background: rgba(0, 0, 0, 0.85);
}

.item-icon-durability-fill {
  display: block;
  height: 2px;
}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 18px;
  height: 18px;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.crosshair {
  mix-blend-mode: difference;
}

.crosshair::before,
.crosshair::after {
  content: "";
  position: absolute;
  background: #e6e6e6;
}

.crosshair::before {
  width: 2px;
  height: 18px;
  left: 8px;
  top: 0;
}

.crosshair::after {
  width: 18px;
  height: 2px;
  left: 0;
  top: 8px;
}

.caps-indicator {
  position: absolute;
  left: 12px;
  bottom: 12px;
  border: 2px solid rgba(0, 0, 0, 0.6);
  background: rgba(12, 12, 12, 0.5);
  color: #d8d8d8;
  padding: 4px 8px;
  font-size: 11px;
  text-shadow: var(--mc-text-shadow);
  user-select: none;
}

.caps-indicator.on {
  color: #7dff6e;
}

/* --- Survival inventory dialog + recipe book --- */

.inventory-panel {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 6;
  background: var(--mc-panel);
  border-style: solid;
  border-width: 3px;
  border-color: var(--mc-bevel-light) var(--mc-bevel-dark) var(--mc-bevel-dark) var(--mc-bevel-light);
  outline: 2px solid rgba(0, 0, 0, 0.8);
  padding: 12px;
  max-height: 92vh;
  overflow-y: auto;
}

.inventory-columns {
  display: flex;
  gap: 14px;
  align-items: stretch;
}

.inventory-heading {
  color: var(--mc-text);
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 6px;
}

.inventory-upper {
  display: flex;
  gap: 12px;
  margin-bottom: 10px;
}

.armor-column {
  display: grid;
  gap: 2px;
}

.inventory-hint {
  align-self: center;
  color: #5a5a5a;
  font-size: 10px;
  line-height: 1.6;
}

.inv-grid {
  display: grid;
  grid-template-columns: repeat(9, 40px);
  gap: 2px;
}

.inv-grid.storage {
  margin-bottom: 10px;
}

.inv-slot {
  position: relative;
  width: 40px;
  height: 40px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  background: var(--mc-slot-well);
  border-style: solid;
  border-width: 2px;
  border-color: var(--mc-bevel-dark) var(--mc-bevel-light) var(--mc-bevel-light) var(--mc-bevel-dark);
}

.inv-slot:hover {
  background: #a3a3a3;
}

.inv-slot.active::after {
  content: "";
  position: absolute;
  inset: -3px;
  border: 2px solid #fefefe;
  outline: 1px solid rgba(0, 0, 0, 0.6);
  pointer-events: none;
  z-index: 1;
}

.inv-slot.pending {
  background: #b8c8e8;
  border-color: #2c3c64 #d8e4ff #d8e4ff #2c3c64;
}

.inv-slot.equipped {
  background: #9dbb8f;
}

.armor-ghost {
  opacity: 0.3;
  filter: grayscale(1);
}

.recipe-book {
  display: flex;
  flex-direction: column;
  min-width: 190px;
  border-left: 2px solid #9a9a9a;
  padding-left: 12px;
}

.recipe-list {
  display: grid;
  gap: 4px;
  align-content: start;
  overflow-y: auto;
  max-height: 360px;
  padding-right: 4px;
}

.recipe-entry {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 7px;
  cursor: pointer;
  background: var(--mc-slot-well);
  border-style: solid;
  border-width: 2px;
  border-color: var(--mc-bevel-dark) var(--mc-bevel-light) var(--mc-bevel-light) var(--mc-bevel-dark);
}

.recipe-entry:hover:not(:disabled) {
  background: #a3a3a3;
}

.recipe-entry:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.recipe-entry:disabled img {
  filter: grayscale(0.9);
}

.recipe-ingredients {
  display: flex;
  align-items: center;
  gap: 8px;
}

.recipe-arrow {
  color: var(--mc-text);
  font-size: 15px;
  font-weight: 700;
}

/* --- Death screen --- */

.death-overlay {
  position: absolute;
  inset: 0;
  background: rgba(124, 10, 10, 0.5);
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: center;
}

.death-content {
  display: grid;
  gap: 14px;
  justify-items: center;
  text-align: center;
}

.death-title {
  font-size: 44px;
  font-weight: 700;
  color: var(--mc-text-light);
  text-shadow: 3px 3px 0 rgba(0, 0, 0, 0.55);
}

.death-sub {
  font-size: 15px;
  color: #f3dcdc;
  text-shadow: var(--mc-text-shadow);
}

.death-content .mc-button {
  min-width: 220px;
}

/* --- Sleep fade-to-black --- */

.sleep-overlay {
  position: absolute;
  inset: 0;
  background: #000;
  z-index: 9;
  opacity: 0;
  pointer-events: none;
  transition: opacity 1.3s ease-in-out;
}

.sleep-overlay.on {
  opacity: 1;
}

@media (max-width: 720px) {
  .hud-bottom {
    bottom: 4px;
  }

  .hotbar-slot {
    width: 38px;
    height: 38px;
  }

  .inventory-columns {
    flex-direction: column;
  }

  .recipe-book {
    border-left: none;
    padding-left: 0;
    border-top: 2px solid #9a9a9a;
    padding-top: 10px;
  }

  .inv-grid {
    grid-template-columns: repeat(9, 32px);
  }

  .inv-slot {
    width: 32px;
    height: 32px;
  }

  .recipe-list {
    max-height: 180px;
  }
}

/* --- Minimap --- */

.minimap {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 4;
  pointer-events: none;
  user-select: none;
}

.minimap-canvas {
  display: block;
  image-rendering: pixelated;
  border-style: solid;
  border-width: 3px;
  border-color: #6c6c6c #2e2e2e #2e2e2e #6c6c6c;
  outline: 2px solid rgba(0, 0, 0, 0.75);
  background: rgba(10, 10, 10, 0.4);
}

@media (max-width: 720px) {
  .minimap-canvas {
    width: 96px !important;
    height: 96px !important;
  }
}

