  background: #b8c8e8;
  border-color: #2c3c64 #d8e4ff #d8e4ff #2c3c64;
}

.inv-slot.equipped {
  background: #9dbb8f;
}

.armor-ghost {
  opacity: 0.3;
  filter: grayscale(1);
}

.recipe-book {
  display: flex;
  flex-direction: column;
  min-width: 190px;
  border-left: 2px solid #9a9a9a;
  padding-left: 12px;
}

.recipe-list {
  display: grid;
  gap: 4px;
  align-content: start;
  overflow-y: auto;
  max-height: 360px;
  padding-right: 4px;
}

.recipe-entry {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 7px;
  cursor: pointer;
  background: var(--mc-tile-well), var(--mc-slot-well);
  border-style: solid;
  border-width: 2px;
  border-color: var(--mc-bevel-dark) var(--mc-bevel-light) var(--mc-bevel-light) var(--mc-bevel-dark);
}

.recipe-entry:hover:not(:disabled) {
  background: #a3a3a3;
}

.recipe-entry:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.recipe-entry:disabled img {
  filter: grayscale(0.9);
}

.recipe-ingredients {
  display: flex;
  align-items: center;
  gap: 8px;
}

.recipe-arrow {
  color: var(--mc-text);
  font-size: 15px;
  font-weight: 700;
}

/* --- Death screen --- */

.death-overlay {
  position: absolute;
  inset: 0;
  background: rgba(124, 10, 10, 0.5);
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: center;
}

.death-content {
  display: grid;
  gap: 14px;
  justify-items: center;
  text-align: center;
}

.death-title {
  font-size: 44px;
  font-weight: 700;
  color: var(--mc-text-light);
  text-shadow: 3px 3px 0 rgba(0, 0, 0, 0.55);
}

.death-sub {
  font-size: 15px;
  color: #f3dcdc;
  text-shadow: var(--mc-text-shadow);
}

.death-content .mc-button {
  min-width: 220px;
}

/* --- Sleep fade-to-black --- */

.sleep-overlay {
  position: absolute;
  inset: 0;
  background: #000;
  z-index: 9;
  opacity: 0;
  pointer-events: none;
  transition: opacity 1.3s ease-in-out;
}

.sleep-overlay.on {
  opacity: 1;
}

@media (max-width: 720px) {
  .hud-bottom {
    bottom: 4px;
  }

  .hotbar-slot {
    width: 38px;
    height: 38px;
  }

  .inventory-columns {
    flex-direction: column;
  }

  .recipe-book {
    border-left: none;
    padding-left: 0;
    border-top: 2px solid #9a9a9a;
    padding-top: 10px;
  }

  .inv-grid {
    grid-template-columns: repeat(9, 32px);
  }

  .inv-slot {
    width: 32px;
    height: 32px;
  }

  .recipe-list {
    max-height: 180px;
  }
}

/* --- Minimap --- */

.minimap {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 4;
  pointer-events: none;
  user-select: none;
}

.minimap-canvas {
  display: block;
  image-rendering: pixelated;
  border-style: solid;
  border-width: 3px;
  border-color: #6c6c6c #2e2e2e #2e2e2e #6c6c6c;
  outline: 2px solid rgba(0, 0, 0, 0.75);
  background: rgba(10, 10, 10, 0.4);
}

@media (max-width: 720px) {
  .minimap-canvas {
    width: 96px !important;
    height: 96px !important;
  }
