/* --- Bottom HUD: status icon rows + the 9-slot hotbar --- */

.hud-bottom {
  position: absolute;
  left: 50%;
  bottom: 6px;
  transform: translateX(-50%);
  z-index: 4;
  display: grid;
  justify-items: center;
  gap: 3px;
  pointer-events: auto;
  user-select: none;
}

.status-bars {
  display: flex;
  justify-content: space-between;
  width: 100%;
  gap: 12px;
}

.status-bars-left,
.status-bars-right {
  display: grid;
  gap: 2px;
}

.status-icon-row {
  display: flex;
  gap: 1px;
}

.status-icon-row.reversed {
  flex-direction: row-reverse;
}

.status-icon-row img {
  image-rendering: pixelated;
  filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, 0.45));
}

.hotbar-area {
  position: relative;
  display: grid;
  justify-items: center;
}

.hotbar-item-name {
  position: absolute;
  top: -34px;
  color: var(--mc-text-light);
  font-size: 15px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
  opacity: 0;
  animation: hotbar-name-fade 2.2s ease-out forwards;
  pointer-events: none;
  white-space: nowrap;
}

@keyframes hotbar-name-fade {
  0% {
    opacity: 0;
  }
  8% {
    opacity: 1;
  }
  70% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

.hotbar {
  display: flex;
  padding: 3px;
  background: rgba(12, 12, 12, 0.5);
  border: 2px solid rgba(0, 0, 0, 0.62);
  outline: 1px solid rgba(255, 255, 255, 0.28);
}

.hotbar-slot {
  position: relative;
  width: 46px;
  height: 46px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  background: rgba(34, 34, 34, 0.42);
  border-style: solid;
  border-width: 2px;
  border-color: rgba(20, 20, 20, 0.85) rgba(125, 125, 125, 0.6) rgba(125, 125, 125, 0.6) rgba(20, 20, 20, 0.85);
}

.hotbar-slot.active::after {
  content: "";
  position: absolute;
  inset: -5px;
  border: 3px solid #fefefe;
  outline: 1px solid rgba(0, 0, 0, 0.55);
  pointer-events: none;
}

.hotbar-slot:hover {
  background: rgba(80, 80, 80, 0.45);
}

/* --- Item icons (shared by hotbar and inventory slots) --- */

.item-icon {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.item-icon img {
  image-rendering: pixelated;
}

.item-icon-count {
  position: absolute;
  right: -4px;
  bottom: -6px;
  font-size: 14px;
  font-weight: 700;
