"use client";

import { type MouseEvent, useCallback, useState } from "react";
import { createPortal } from "react-dom";

export type TooltipContent = { title: string; lines?: string[] } | null;

/**
 * Minecraft-style item tooltip: a near-black box with a violet gradient border
 * that follows the cursor (matching the game and sidestepping clipping inside
 * the scrollable inventory). It renders in a portal on document.body and is
 * pointer-events:none, so it can never intercept the canvas click that
 * re-acquires pointer lock. During locked play the cursor is hidden and slots
 * aren't hover-reachable, so the tooltip simply never shows.
 *
 * Usage: `const { tooltip, bind } = useItemTooltip();` then spread
 * `{...bind(content)}` onto each hoverable element and render `{tooltip}` once.
 * Pass `null` content for empty/non-hover targets to disable the tooltip there.
 * Keep each element's aria-label — the tooltip is aria-hidden.
 */
export function useItemTooltip() {
  const [content, setContent] = useState<TooltipContent>(null);
  const [pos, setPos] = useState({ x: 0, y: 0 });

  const track = useCallback((e: MouseEvent) => setPos({ x: e.clientX, y: e.clientY }), []);

  const bind = useCallback(
    (c: TooltipContent) =>
      c
        ? {
            onMouseEnter: (e: MouseEvent) => {
              setContent(c);
              setPos({ x: e.clientX, y: e.clientY });
            },
            onMouseMove: track,
            onMouseLeave: () => setContent(null)
          }
        : {},
    [track]
  );

  let tooltip: React.ReactNode = null;
  if (content && typeof document !== "undefined") {
    // Flip to the cursor's left near the right edge so wide tooltips stay on screen.
    const flip = typeof window !== "undefined" && pos.x > window.innerWidth - 300;
    const style = flip ? { right: window.innerWidth - pos.x + 14, top: pos.y + 14 } : { left: pos.x + 14, top: pos.y + 14 };
    tooltip = createPortal(
      <div className="item-tooltip" style={style} aria-hidden>
        <span className="item-tooltip-title">{content.title}</span>
        {content.lines?.map((line, i) => (
          <span key={i} className="item-tooltip-line">
            {line}
          </span>
        ))}
      </div>,
      document.body
    );
  }

  return { tooltip, bind };
}

"use client";

import { useEffect } from "react";
import DeathScreen from "@/components/game/DeathScreen";
import DebugOverlay from "@/components/game/DebugOverlay";
import Hotbar from "@/components/game/Hotbar";
import InventoryPanel from "@/components/game/InventoryPanel";
import PauseMenu from "@/components/game/PauseMenu";
import SleepOverlay from "@/components/game/SleepOverlay";
import StatusBars from "@/components/game/StatusBars";
import { useMinecraftGame } from "@/lib/game/useMinecraftGame";
import { installUiTiles } from "@/lib/ui/chromeTiles";

export default function MinecraftGame() {
  const {
    attachMount,
    attachMinimap,
    locked,
    rendererError,
    selectedSlot,
    setSelectedSlot,
    capsActive,
    inventoryOpen,
    inventory,
    equippedArmor,
    armorPoints,
    hearts,
    hunger,
    daylightPercent,
    passiveCount,
    hostileCount,
    respawnSeconds,
    paused,
    sleeping,
    craftingStation,
    debugOpen,
    debug,
    saveMessage,
    audioSettings,
    updateAudioSettings,
    skinId,
    updateSkin,
    hotbarSlots,
    recipes,
    maxHearts,
    maxHunger,
    canCraft,
    craft,
    swapInventorySlots,
    toggleEquipArmor,
    resumeNow,
    respawnNow,
    saveNow,
    loadNow,
    resetNow
  } = useMinecraftGame();

  useEffect(() => {
    installUiTiles();
  }, []);

  if (rendererError) {
    return (
      <div className="game-root">
        <div className="renderer-error">
          <h2>Could not start the 3D renderer</h2>
          <p>WebGL appears to be unavailable in this browser ({rendererError}).</p>
          <p>Try enabling hardware acceleration or switching browsers, then reload.</p>
        </div>
      </div>
    );
  }

  const showClickHint = !locked && !paused && !inventoryOpen && respawnSeconds === 0;

  return (
    <div className="game-root">
      <div ref={attachMount} className="game-canvas-wrap" />

      {debugOpen ? <DebugOverlay debug={debug} passiveCount={passiveCount} hostileCount={hostileCount} daylightPercent={daylightPercent} /> : null}

      {showClickHint ? <div className="click-hint">Click to play</div> : null}

      {saveMessage && !paused ? (
        <div className="hud-toast" role="status">
          {saveMessage}
        </div>
      ) : null}

      <div ref={attachMinimap} className="minimap" data-testid="minimap" />

      <div className="hud-bottom">
        <StatusBars hearts={hearts} maxHearts={maxHearts} hunger={hunger} maxHunger={maxHunger} armorPoints={armorPoints} />
        <Hotbar inventory={inventory} selectedSlot={selectedSlot} hotbarSlots={hotbarSlots} onSelectSlot={setSelectedSlot} />
      </div>

