/* Full-screen overlays: pause menu, F3 debug readout, click-to-play hint. */

.pause-overlay {
  position: absolute;
  inset: 0;
  z-index: 9;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.55);
}

.pause-menu {
  display: grid;
  gap: 8px;
  width: min(92vw, 320px);
  justify-items: stretch;
}

.pause-title {
  text-align: center;
  color: var(--mc-text-light);
  font-size: 22px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
  margin-bottom: 10px;
}

.mc-button {
  padding: 9px 16px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 700;
  color: var(--mc-text-light);
  text-shadow: var(--mc-text-shadow);
  background: var(--mc-tile-button), var(--mc-button);
  border-style: solid;
  border-width: 2px;
  border-color: #a8a8a8 #2c2c2c #2c2c2c #a8a8a8;
  outline: 2px solid rgba(0, 0, 0, 0.85);
  cursor: pointer;
  user-select: none;
}

.mc-button:hover,
.mc-button:focus-visible {
  background: var(--mc-button-hover);
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.mc-button:active {
  border-color: #2c2c2c #a8a8a8 #a8a8a8 #2c2c2c;
}

.mc-button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.mc-button.danger {
  background: #8c3a34;
  border-color: #c98179 #4a1713 #4a1713 #c98179;
}

.pause-reset-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.pause-sound {
  display: grid;
  gap: 8px;
  margin-top: 4px;
}

.pause-sound-row {
  display: grid;
  grid-template-columns: 64px 1fr;
  align-items: center;
  gap: 10px;
  color: var(--mc-text-light);
  font-size: 13px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
}

.pause-skins {
  display: grid;
  gap: 6px;
  margin-top: 4px;
}

.pause-skins-title {
  color: var(--mc-text-light);
  font-size: 13px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
}

.pause-skins-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.skin-swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 6px 4px;
  font-family: inherit;
  font-size: 11px;
  font-weight: 700;
  color: var(--mc-text-light);
  text-shadow: var(--mc-text-shadow);
  background: var(--mc-tile-button), var(--mc-button);
  border-style: solid;
  border-width: 2px;
  border-color: #a8a8a8 #2c2c2c #2c2c2c #a8a8a8;
  cursor: pointer;
  user-select: none;
}

.skin-swatch:hover,
.skin-swatch:focus-visible {
  background: var(--mc-button-hover);
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.skin-swatch[aria-pressed="true"] {
  background: var(--mc-button-hover);
  border-color: #f0be3c;
  outline: 1px solid rgba(240, 190, 60, 0.6);
}

.mc-slider {
  appearance: none;
  width: 100%;
  height: 18px;
  margin: 0;
  background: var(--mc-tile-button), var(--mc-button);
  border-style: solid;
  border-width: 2px;
  border-color: #2c2c2c #a8a8a8 #a8a8a8 #2c2c2c;
  outline: 2px solid rgba(0, 0, 0, 0.85);
  cursor: pointer;
}

.mc-slider:focus-visible {
  background: var(--mc-button-hover);
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.mc-slider::-webkit-slider-thumb {
  appearance: none;
  width: 12px;
