* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  /* --mc-font (Pixelify Sans, set on <html> by next/font) already carries the
     monospace fallback list, so text renders even before the font loads. */
  font-family: var(--mc-font), var(--mc-font-mono);
  background: #87bfff;
}

.game-root {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at 50% 20%, #bfe4ff 0%, #7ab2f2 45%, #5084c8 100%);
}

.game-canvas-wrap {
  position: absolute;
  inset: 0;
}

/* Subtle always-on vignette over the 3D world; sits above the canvas but below
   all HUD (z-index >= 4) and never blocks the click that acquires pointer lock. */
.vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background: radial-gradient(ellipse at center, rgba(0, 0, 0, 0) 55%, rgba(0, 0, 0, var(--mc-vignette)) 100%);
}

@keyframes mc-fade-in {
