  border-style: solid;
  border-width: 3px;
  border-color: var(--mc-bevel-light) var(--mc-bevel-dark) var(--mc-bevel-dark) var(--mc-bevel-light);
  color: var(--mc-text);
  padding: 18px 22px;
  text-align: center;
}

