1	import { acquirePointerLock, calmDaytime, expect, itemCount, playerPosition, test } from "./helpers";
2	
3	test("boots without errors and renders the world", async ({ gamePage: page }) => {
4	  await expect(page.locator(".game-canvas-wrap canvas")).toBeVisible();
5	  await expect(page.getByTestId("hotbar")).toBeVisible();
6	  const triangles = await page.evaluate(() => window.__monecraft!.renderer.renderedTriangles());
7	  expect(triangles).toBeGreaterThan(0);
8	
9	  // The audio director is wired up (still locked pre-gesture — the shared
10	  // console-error fixture proves boot stays clean without any unlock).
11	  expect(await page.evaluate(() => Boolean(window.__monecraft!.audio))).toBe(true);
12	
13	  // The engine is alive: the day clock advances between frames.
14	  const clock1 = await page.evaluate(() => window.__monecraft!.engine.state.dayClock);
15	  await page.waitForTimeout(200);
16	  const clock2 = await page.evaluate(() => window.__monecraft!.engine.state.dayClock);
17	  expect(clock2).toBeGreaterThan(clock1);
18	});
19	
20	test("pointer-lock flow enables WASD movement", async ({ gamePage: page }) => {
21	  await calmDaytime(page);
22	  await acquirePointerLock(page);
23	
24	  await page.waitForTimeout(500); // settle onto the ground
25	  const before = await playerPosition(page);
26	  await page.keyboard.down("w");
27	  await page.waitForTimeout(700);
28	  await page.keyboard.up("w");
29	  const after = await playerPosition(page);
30	
31	  const moved = Math.hypot(after.x - before.x, after.z - before.z);
32	  expect(moved).toBeGreaterThan(0.5);
33	});
34	
35	test("inventory opens and crafting works end to end", async ({ gamePage: page }) => {
36	  await calmDaytime(page);
37	  await page.keyboard.press("i");
38	  const panel = page.locator(".inventory-panel");
39	  await expect(panel).toBeVisible();
40	
41	  const planksBefore = await itemCount(page, "planks"); // starter loadout: 20
42	  await panel.getByRole("button", { name: "2 Wood -> 4 Planks" }).click();
43	
44	  expect(await itemCount(page, "planks")).toBe(planksBefore + 4);
45	  expect(await itemCount(page, "wood")).toBe(62);
46	  // The UI re-rendered from the new snapshot: the planks stack count updated.
47	  await expect(panel.locator('.inv-slot[title="Planks"]').first()).toContainText(`${planksBefore + 4}`);
48	
49	  await page.keyboard.press("i");
50	  await expect(panel).not.toBeVisible();
51	});
52	
53	test("holding the mouse mines the block underfoot", async ({ gamePage: page }) => {
54	  await calmDaytime(page);
55	  await acquirePointerLock(page);
56	  await page.waitForTimeout(1000); // settle (slow CI renderers need the margin)
57	
58	  // Aim straight down from the center of the cell (a ray origin exactly on a
59	  // cell boundary may target the diagonal neighbor — see docs/testing.md).
60	  await page.evaluate(() => {
61	    const { player } = window.__monecraft!.engine.state;
62	    player.pitch = -Math.PI / 2 + 0.02;
63	    player.position.x = Math.floor(player.position.x) + 0.5;
64	    player.position.z = Math.floor(player.position.z) + 0.5;
65	  });
66	
67	  await page.mouse.down();
68	  // Generous timeout: CI renders with software GL at single-digit FPS.
69	  await expect.poll(async () => page.evaluate(() => window.__monecraft!.engine.state.blockChanges.changes().length), { timeout: 30000 }).toBeGreaterThan(0);
70	  await page.mouse.up();
71	});
72	
73	test("right-click still places a block when not aimed at an interactive one", async ({ gamePage: page }) => {
74	  // The bed/furnace interact dispatcher sits in front of placement; this guards
75	  // that a non-interactive target still falls through to placing a block.
76	  await calmDaytime(page);
77	  await acquirePointerLock(page);
78	  await page.waitForTimeout(1000); // settle
79	
80	  // Carve a clear lane ending in a stone backstop, dead ahead at eye height.
81	  const placed = await page.evaluate(() => {
82	    const state = window.__monecraft!.engine.state;
83	    const ex = Math.floor(state.player.position.x);
84	    const ez = Math.floor(state.player.position.z);
85	    state.player.position.x = ex + 0.5;
86	    state.player.position.z = ez + 0.5;
87	    state.player.yaw = 0;
88	    state.player.pitch = 0;
89	    const ey = Math.floor(state.player.position.y + 1.62);
90	    // 1 = Grass, 0 = Air, 3 = Stone (BlockId enum values).
91	    state.blockChanges.set(ex, ey, ez - 1, 0);
92	    state.blockChanges.set(ex, ey, ez - 2, 0);
93	    state.blockChanges.set(ex, ey, ez - 3, 3);
94	    state.selectedSlot = 0; // starter grass blocks
95	    const before = state.world.get(ex, ey, ez - 2);
96	    window.__monecraft!.engine.dispatch({ type: "placeBlock" });
97	    const after = state.world.get(ex, ey, ez - 2);
98	    return { before, after };
99	  });
100	  expect(placed.before).toBe(0); // air
101	  expect(placed.after).toBe(1); // grass placed
102	});
103	
104	test("V cycles the camera views and the scene keeps rendering", async ({ gamePage: page }) => {
105	  await calmDaytime(page);
106	  const cameraMode = () => page.evaluate(() => window.__monecraft!.engine.state.cameraMode);
107	
108	  expect(await cameraMode()).toBe("first");
109	  await page.keyboard.press("v");
110	  expect(await cameraMode()).toBe("third-rear");
111	  // The third-person scene (player body included) still draws.
112	  await expect.poll(() => page.evaluate(() => window.__monecraft!.renderer.renderedTriangles())).toBeGreaterThan(0);
113	
114	  await page.keyboard.press("v");
115	  expect(await cameraMode()).toBe("third-front");
116	  await page.keyboard.press("v");
117	  expect(await cameraMode()).toBe("first");
118	
119	  // V keeps working from the pause menu (render-only, like Minecraft F5).
120	  await page.keyboard.press("Escape"); // unlocked, so Escape pauses directly
121	  await expect(page.getByRole("button", { name: "Back to Game" })).toBeVisible();
122	  await page.keyboard.press("v");
123	  expect(await cameraMode()).toBe("third-rear");
124	  await page.keyboard.press("Escape"); // resume
125	});
126	
127	test("the pause menu freezes the game and resumes it", async ({ gamePage: page }) => {
128	  await calmDaytime(page);
129	  await page.keyboard.press("Escape"); // unlocked, so Escape pauses directly
130	  await expect(page.getByRole("button", { name: "Back to Game" })).toBeVisible();
131	
132	  const clock1 = await page.evaluate(() => window.__monecraft!.engine.state.dayClock);
133	  await page.waitForTimeout(250);
134	  const clock2 = await page.evaluate(() => window.__monecraft!.engine.state.dayClock);
135	  expect(clock2).toBe(clock1);
136	
137	  await page.getByRole("button", { name: "Back to Game" }).click();
138	  await expect(page.getByRole("button", { name: "Back to Game" })).not.toBeVisible();
139	  await page.waitForTimeout(250);
140	  expect(await page.evaluate(() => window.__monecraft!.engine.state.dayClock)).toBeGreaterThan(clock2);
141	});
142	
143	test("picking a skin persists across a reload", async ({ gamePage: page }) => {
144	  await calmDaytime(page);
145	  await page.keyboard.press("Escape"); // unlocked, so Escape pauses directly
146	  await page.getByRole("button", { name: "Robot skin" }).click();
147	
148	  const stored = await page.evaluate(() => localStorage.getItem("minecraft_skin_v1"));
149	  expect(JSON.parse(stored!)).toEqual({ skinId: "robot" });
150	
151	  await page.reload();
152	  await page.waitForFunction(() => window.__monecraft !== undefined, undefined, { timeout: 30000 });
153	  await page.keyboard.press("Escape");
154	  await expect(page.getByRole("button", { name: "Robot skin" })).toHaveAttribute("aria-pressed", "true");
155	  await expect(page.getByRole("button", { name: "Steve skin" })).toHaveAttribute("aria-pressed", "false");
156	});
157	
158	test("saving from the pause menu persists the world across a reload", async ({ gamePage: page }) => {
159	  await calmDaytime(page);
160	  const seed = await page.evaluate(() => window.__monecraft!.engine.state.world.seed);
161	  const positionBefore = await playerPosition(page);
162	
