      pool.count = last;
      continue; // re-process the slot that was swapped in
    }
    const dragF = Math.max(0, 1 - pool.drag[i] * d);
    pool.vy[i] -= pool.gravity[i] * d;
    pool.vx[i] *= dragF;
    pool.vy[i] *= dragF;
    pool.vz[i] *= dragF;
    pool.px[i] += pool.vx[i] * d;
    pool.py[i] += pool.vy[i] * d;
    pool.pz[i] += pool.vz[i] * d;
    i += 1;
  }
}

