  this.playerVisuals.triggerSwing();
}

/** Spawns particle bursts for one-shot gameplay events (parallel to audio). */
handleEvent(event: GameEvent, state: GameState): void {
  switch (event.type) {
    case "blockBroken":
      this.particles.emitBurst({
        x: event.x + 0.5,
        y: event.y + 0.5,
        z: event.z + 0.5,
        count: 10,
        color: BLOCK_COLORS[event.blockId] ?? [0.6, 0.6, 0.6],
        speed: 3.2,
        spread: 1.0,
        gravity: 14,
        drag: 1.6,
        life: [0.35, 0.7],
        size: 0.16,
        colorJitter: 0.08
      });
      break;
    case "blockPlaced":
      this.particles.emitBurst({
        x: event.x + 0.5,
        y: event.y + 0.5,
        z: event.z + 0.5,
        count: 6,
        color: BLOCK_COLORS[event.blockId] ?? [0.6, 0.6, 0.6],
        speed: 1.2,
        spread: 0.6,
        gravity: 6,
        drag: 2.2,
        life: [0.25, 0.45],
        size: 0.12,
        upBias: 0.6
      });
      break;
    case "mobDied":
      this.particles.emitBurst({
        x: event.x,
        y: event.y + 0.4,
        z: event.z,
        count: 14,
        color: hexToRgb(MOB_TEMPLATES[event.kind].modelArgs[0] as number),
        speed: 2.6,
        spread: 1.4,
        gravity: 10,
        drag: 1.4,
        life: [0.4, 0.8],
        size: 0.18
      });
      break;
    case "ateFood":
      this.particles.emitBurst({
        x: state.player.position.x,
        y: state.player.position.y + 1.4,
        z: state.player.position.z,
        count: 5,
        color: [0.82, 0.6, 0.4],
        speed: 1.6,
        spread: 0.8,
        gravity: 12,
        drag: 1.5,
        life: [0.25, 0.5],
        size: 0.1
      });
      break;
    case "landed":
      this.particles.emitBurst({
        x: state.player.position.x,
        y: state.player.position.y,
        z: state.player.position.z,
        count: Math.min(12, 3 + Math.floor(event.impact)),
        color: [0.7, 0.62, 0.5],
        speed: 0.8 + event.impact * 0.12,
        spread: 1.2,
        gravity: 8,
        drag: 2.5,
        life: [0.2, 0.45],
        size: 0.13,
        upBias: 0.4
      });
      break;
    case "jumped":
      this.particles.emitBurst({
        x: state.player.position.x,
        y: state.player.position.y,
        z: state.player.position.z,
        count: 4,
        color: [0.7, 0.62, 0.5],
        speed: 1.0,
        spread: 1.0,
        gravity: 8,
        drag: 2.5,
        life: [0.15, 0.35],
        size: 0.11
      });
      break;
  }
}

/** Kicks a small dust puff every couple of strides while walking on the ground. */
private emitFootstepDust(state: GameState): void {
