        y: state.player.position.y + 1.4,
        z: state.player.position.z,
        count: 5,
        color: [0.82, 0.6, 0.4],
        speed: 1.6,
        spread: 0.8,
        gravity: 12,
        drag: 1.5,
        life: [0.25, 0.5],
        size: 0.1
      });
      break;
    case "landed":
      this.particles.emitBurst({
        x: state.player.position.x,
        y: state.player.position.y,
        z: state.player.position.z,
        count: Math.min(12, 3 + Math.floor(event.impact)),
        color: [0.7, 0.62, 0.5],
        speed: 0.8 + event.impact * 0.12,
        spread: 1.2,
        gravity: 8,
        drag: 2.5,
        life: [0.2, 0.45],
        size: 0.13,
        upBias: 0.4
      });
